// The one scheduled workflow (spec 0003 T12, R7c): a known merchant's
// own category, below the household's configured threshold, past its
// configured quiet period -- auto-confirmed via the quiet route. The
// query below is a convenience filter; transaction_agent_confirm_guard
// re-checks every one of R7c's conditions at the database, so a bug
// here can only under-confirm, never wrongly confirm.
const crypto = require('crypto');
const http = require('http');
const { URL } = require('url');

const PG = 'http://postgrest:3000';

function b64url(buf) {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function mintAgentToken(memberId) {
  const header = b64url(Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })));
  const payload = b64url(Buffer.from(JSON.stringify({ role: 'hh_agent', member_id: memberId, exp: Math.floor(Date.now() / 1000) + 60 })));
  const signingInput = `${header}.${payload}`;
  const signature = b64url(crypto.createHmac('sha256', $env.PGRST_JWT_SECRET).update(signingInput).digest());
  return `${signingInput}.${signature}`;
}

function httpJson(method, url, headers, body) {
  return new Promise((resolve, reject) => {
    const bodyStr = body !== undefined ? JSON.stringify(body) : undefined;
    const u = new URL(url);
    const options = {
      hostname: u.hostname, port: u.port, path: u.pathname + u.search, method,
      headers: Object.assign({ 'Content-Type': 'application/json' }, headers, bodyStr ? { 'Content-Length': Buffer.byteLength(bodyStr) } : {}),
    };
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        let parsed = null;
        try { parsed = data ? JSON.parse(data) : null; } catch (e) { parsed = data; }
        resolve({ status: res.statusCode, body: parsed });
      });
    });
    req.on('error', reject);
    if (bodyStr) req.write(bodyStr);
    req.end();
  });
}

async function main() {
  // No member is asking in this moment, but A30 holds regardless: no
  // write is ever attributed to no one. This runs as the agent acting
  // under the standing rule the admin who configured the threshold
  // already gave (ADR 0042's "compose" shape, backed by that admin's
  // own prior authority) -- a read using no member_id at all is the
  // one call this job makes before it has anyone to act as.
  const readToken = mintAgentToken(null);
  const readAuth = { Authorization: `Bearer ${readToken}` };
  const settingsRes = await httpJson('GET', `${PG}/household_setting?key=in.(auto_confirm_threshold_minor,auto_confirm_quiet_period_hours)&select=key,value,updated_by`, readAuth);
  const settings = {};
  for (const row of settingsRes.body || []) settings[row.key] = row;
  const threshold = Number(settings.auto_confirm_threshold_minor && settings.auto_confirm_threshold_minor.value);
  const quietHours = Number(settings.auto_confirm_quiet_period_hours && settings.auto_confirm_quiet_period_hours.value);
  const configuringAdmin = settings.auto_confirm_threshold_minor && settings.auto_confirm_threshold_minor.updated_by;

  if (!threshold || threshold <= 0 || !quietHours || !configuringAdmin) {
    return [{ json: { confirmed: [], note: 'auto-confirmation is not configured' } }];
  }

  const token = mintAgentToken(configuringAdmin);
  const auth = { Authorization: `Bearer ${token}` };

  const cutoff = new Date(Date.now() - quietHours * 3600 * 1000).toISOString();
  const candidatesRes = await httpJson(
    'GET',
    `${PG}/transaction?confirmation_state=eq.unconfirmed&category_source=eq.merchant_default&created_at=lt.${encodeURIComponent(cutoff)}&select=id`,
    auth
  );
  const candidates = candidatesRes.body || [];

  const confirmed = [];
  for (const candidate of candidates) {
    const postingsRes = await httpJson('GET', `${PG}/posting?transaction_id=eq.${candidate.id}&amount=gt.0&select=amount`, auth);
    const expensePosting = (postingsRes.body || [])[0];
    if (!expensePosting || Math.abs(expensePosting.amount) >= threshold) continue;

    const patched = await httpJson('PATCH', `${PG}/transaction?id=eq.${candidate.id}`, Object.assign({ Prefer: 'return=minimal' }, auth), {
      confirmation_state: 'confirmed', confirmation_route: 'quiet', confirmed_at: new Date().toISOString(),
    });
    if (patched.status >= 200 && patched.status < 300) confirmed.push(candidate.id);
  }

  return [{ json: { confirmed, checked: candidates.length } }];
}

return main();
